-- Tenant-owned like every other tenant table: forced row level security and a cascading tenant foreign key.
ALTER TABLE "billing_charges" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "billing_charges" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "billing_charges" USING (tenant_id = rd_current_tenant()) WITH CHECK (tenant_id = rd_current_tenant());
ALTER TABLE "billing_charges" ADD CONSTRAINT billing_charges_tenant_fk FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE;

ALTER TABLE "billing_consents" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "billing_consents" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "billing_consents" USING (tenant_id = rd_current_tenant()) WITH CHECK (tenant_id = rd_current_tenant());
ALTER TABLE "billing_consents" ADD CONSTRAINT billing_consents_tenant_fk FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE;

-- Consent and charge records are evidence (disputes, chargebacks): the application can add them, never rewrite them.
GRANT SELECT, INSERT ON TABLE "billing_charges", "billing_consents" TO talkivio_app_role;
REVOKE UPDATE, DELETE ON TABLE "billing_charges", "billing_consents" FROM talkivio_app_role;

