-- Workspaces the billing sweep has work for: a trial reminder or trial end, a renewal, a retry, an expired grace
-- period. Returns ids only; the sweep then reads each account under its own tenant (RLS).
CREATE OR REPLACE FUNCTION rd_billing_due(p_now timestamptz, p_reminder_days int)
RETURNS TABLE (tenant_id uuid)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT b.tenant_id FROM billing_accounts b JOIN tenants t ON t.id = b.tenant_id
  WHERE t.deleted_at IS NULL AND t.status = 'active' AND NOT b.needs_review
    AND (b.charging_until IS NULL OR b.charging_until < p_now)
    AND (
      (b.state = 'trialing' AND (b.trial_ends_at <= p_now
        OR (b.trial_reminder_sent_at IS NULL AND b.trial_ends_at <= p_now + make_interval(days => p_reminder_days))))
      OR (b.state = 'active' AND b.current_period_end <= p_now)
      OR (b.state = 'past_due' AND (b.next_attempt_at <= p_now OR b.grace_ends_at <= p_now))
    )
  ORDER BY b.tenant_id
  LIMIT 500
$$;
REVOKE ALL ON FUNCTION rd_billing_due(timestamptz, int) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION rd_billing_due(timestamptz, int) TO talkivio_app_role;
